// Регресс «готовность к выпуску 19.10.2026» — группа 3: нусахи по СОДЕРЖИМОМУ (урок L-20261019-1: сравнивать тексты, а не переключатель).
// Логика — как скрипты проверки 19.10 (dump.py: страницы 1…N через «המשך»; ana.py: маркеры по тексту без огласовок;
// bracha.py: строка «מקור» у брахот в двух нусахах; swnus.py: «בחירת נוסח» → нусах → «החלף»).
// Факты 19.10: שחרית 66/57, מנחה 8/11, ערבית 15/16 страниц (не проверяются — клиент дополняет тексты, #16933ca6);
// «ויצמח פורקנה» только в ספרד; קדושה «נקדש את שמך» (אשכנז) / «נקדישך ונעריצך» (ספרד); «שלום רב» (אשכנז מנחה/ערבית) / «שים שלום»
// (ספרד מנחה); שחרית: אשכנז «ברוך שאמר» (стр. 26) раньше «הודו» (27), ספרד «הודו» (17) раньше «ברוך שאמר» (20).
// Брахот: «מקור: Sefaria.org — Siddur Ashkenaz …» / «… Siddur Sefard …». «בבית האבל», «קריאה לתענית ציבור» — только у пользователя ספרד
// (решение 19.10, context.md). Нусах внутри молитвы не запоминается (handoff 19.10) — в конце возвращаем «אשכנזי».
// Кейсы: .qa/tests/readiness/RD-03-nusach-content.md.
import { expect } from '@wdio/globals';
import { byTextContains, byTextMatches, scrollToText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { shown, ensureNusach } from '../_lib/app-0710.ts';
import {
  goHome, dumpPrayerIn, firstPage, stripNikud, saveArtifact, withProfileNusach, openCatalog, searchCatalog, catalogCard,
  openCatalogPrayer, buttonStartsWith, counterNM,
} from '../_lib/readiness-1910.ts';

type Dump = { header: string; total: number; pages: string[] };
const D: Record<string, Dump> = {};
const has = (d: Dump, re: RegExp) => firstPage(d.pages, re) > 0;

const RE = {
  vayatzmach: /ויצמח\s+פו?רקנה/,
  nakdish: /נקדישך\s+ונעריצך/,
  nekadesh: /נקדש\s+את\s+שמך/,
  shalomRav: /שלום\s+רב\s+על\s+ישראל/,
  simShalom: /שים\s+שלום/,
  hodu: /הודו\s+ל\S*\s+קראו\s+בשמו/,
  baruchSheamar: /ברוך\s+שאמר\s+והיה/,
};

describe('Готовность 19.10 — нусахи по содержимому', () => {
  before(async function () {
    this.timeout(3600000);   // שחרית 66+57 страниц
    for (const [title, key] of [['שחרית', 'shacharit'], ['מנחה', 'mincha'], ['ערבית', 'arvit']] as const) {
      D[`${key}-ash`] = await dumpPrayerIn(title, 'אשכנזי');
      D[`${key}-sfard`] = await dumpPrayerIn(title, 'ספרדי');
      await ensureNusach('אשכנזי');
    }
    saveArtifact('nusach-dump.json', D);
    for (const [k, d] of Object.entries(D)) console.log(`[RD-03] ${k}: ${d.header}, страниц ${d.total}`);
  });
  after(async () => { await goHome().catch(() => {}); });

  it('RD-03a ספרד: «ויצמח פורקנה» (קדיש) в שחרית/מנחה/ערבית, «נקדישך ונעריצך» в שחרית/מנחה, «שים שלום» в מנחה; в שחרית «הודו» раньше «ברוך שאמר» F-37 F-102 L-20261019-1 @prod-safe', () => {
    for (const k of ['shacharit-sfard', 'mincha-sfard', 'arvit-sfard']) expect(has(D[k], RE.vayatzmach)).toBe(true);
    for (const k of ['shacharit-sfard', 'mincha-sfard']) expect(has(D[k], RE.nakdish)).toBe(true);
    expect(has(D['mincha-sfard'], RE.simShalom)).toBe(true);
    expect(has(D['mincha-sfard'], RE.shalomRav)).toBe(false);
    const hodu = firstPage(D['shacharit-sfard'].pages, RE.hodu);
    const bs = firstPage(D['shacharit-sfard'].pages, RE.baruchSheamar);
    expect(hodu).toBeGreaterThan(0);
    expect(bs).toBeGreaterThan(0);
    expect(hodu).toBeLessThan(bs);
  });

  it('RD-03b אשכנז: «נקדש את שמך» в שחרית/מנחה, «שלום רב» в מנחה и ערבית, нет «ויצמח פורקנה»; в שחרית «ברוך שאמר» раньше «הודו» F-37 F-102 L-20261019-1 @prod-safe', () => {
    for (const k of ['shacharit-ash', 'mincha-ash']) expect(has(D[k], RE.nekadesh)).toBe(true);
    for (const k of ['mincha-ash', 'arvit-ash']) expect(has(D[k], RE.shalomRav)).toBe(true);
    for (const k of ['shacharit-ash', 'mincha-ash', 'arvit-ash']) expect(has(D[k], RE.vayatzmach)).toBe(false);
    for (const k of ['shacharit-ash', 'mincha-ash']) expect(has(D[k], RE.nakdish)).toBe(false);
    const hodu = firstPage(D['shacharit-ash'].pages, RE.hodu);
    const bs = firstPage(D['shacharit-ash'].pages, RE.baruchSheamar);
    expect(bs).toBeGreaterThan(0);
    expect(hodu).toBeGreaterThan(bs);
  });

  it('RD-03c Тексты двух нусахов различаются (не один и тот же текст под разной меткой) F-37 AC2 L-20261019-1 @prod-safe', () => {
    for (const k of ['shacharit', 'mincha', 'arvit']) {
      const a = stripNikud(D[`${k}-ash`].pages.join('\n'));
      const s = stripNikud(D[`${k}-sfard`].pages.join('\n'));
      expect(D[`${k}-ash`].header).toContain('אשכנזי');
      expect(D[`${k}-sfard`].header).toContain('ספרדי');
      expect(a).not.toBe(s);
    }
  });

  it('RD-03d ברכות: у каждой брахи источник своего נוסח — «Siddur Ashkenaz» в אשכנזי, «Siddur Sefard» в ספרדי (11 брахот) F-93 F-102 AC2 @prod-safe', async function () {
    this.timeout(1800000);
    const names = ['נטילת ידים והמוציא', 'בורא מיני מזונות', 'בורא פרי הגפן', 'בורא פרי העץ', 'בורא פרי האדמה', 'שהכל נהיה בדברו',
      'ברכת המזון', 'ברכה אחרונה מעין שלוש', 'בורא נפשות', 'אשר יצר', 'תפילת הדרך'];
    const bad: string[] = [];
    for (const n of names) {
      await goHome();
      await goTab('ברכות');
      const card = await buttonStartsWith(`${n}, נוסח`);
      if (!(await shown(card))) await scrollToText(n);
      await card.click();
      await ensureNusach('אשכנזי');
      await scrollToText('מקור:');
      if (!(await shown(byTextContains('Siddur Ashkenaz')))) bad.push(`${n} אשכנזי`);
      await ensureNusach('ספרדי');
      await scrollToText('מקור:');
      if (!(await shown(byTextContains('Siddur Sefard')))) bad.push(`${n} ספרדי`);
      await ensureNusach('אשכנזי');
    }
    expect(bad).toEqual([]);
  });

  it('RD-03e Пользователь ספרד видит и открывает «בבית האבל» и «קריאה לתענית ציבור»; у אשכנז их нет (решение 19.10) F-46 F-40 @data', async function () {
    this.timeout(900000);
    const extra = ['בבית האבל', 'קריאה לתענית ציבור'];
    await withProfileNusach('ספרד', async () => {
      for (const t of extra) {
        await openCatalogPrayer(t);
        const [, total] = await counterNM();
        expect(total).toBeGreaterThan(0);
        await expect(byTextMatches('.*[\\u05B0-\\u05C7].*')).toBeExisting();   // текст с ניקוד
      }
    });
    // Профиль снова אשכנז (withProfileNusach вернул) — карточек нет.
    await openCatalog();
    for (const t of extra) {
      await searchCatalog(t);
      expect(await shown(catalogCard(t))).toBe(false);
    }
    await searchCatalog('');
  });

  it('RD-03f שחרית ספרד содержит «מודה אני», ציצית, טלית, תפילין, «מה טובו», «אדון עולם», «יגדל» (клиент дополнит сам — инструмент #16933ca6 готов 21.10; не баг продукта, ждём контент клиента) #16933ca6 @client-content @prod-safe', () => {
    const t = stripNikud(D['shacharit-sfard'].pages.join('\n'));
    const need: Record<string, RegExp> = {
      'מודה אני': /מודה\s+אני\s+לפניך/, 'ציצית': /על\s+מצות\s+ציצית/, 'טלית': /להתעטף\s+בציצית/, 'תפילין': /להניח\s+תפילין/,
      'מה טובו': /מה\s+טו?בו\s+אהליך/, 'אדון עולם': /אדון\s+עולם/, 'יגדל': /יגדל\s+אלהים\s+חי/,
    };
    const missing = Object.entries(need).filter(([, re]) => !re.test(t)).map(([k]) => k);
    console.log(`[RD-03f] нет в שחרית ספרד: ${missing.join(', ') || '—'}`);
    expect(missing).toEqual([]);
  });
});

